#define APB4SLVADDRESSBLOCK__NSEC_STATUS__RAZWI_0__FIELD (0x1fff << APB4SLVADDRESSBLOCK__NSEC_STATUS__RAZWI_0__SHIFT)
                
/* field: APB4SLVADDRESSBLOCK.NSEC_STATUS.STAT_ALLCHIDLE, pos: [17:17] -- All Non-Secure Channel Idle Status. Set to '1' whenever all Non-secure DMA channel is in idle state after at least one channel was running. Cleared by writing '1' to this bit.*/
#define APB4SLVADDRESSBLOCK__NSEC_STATUS__STAT_ALLCHIDLE__SHIFT 17
#define APB4SLVADDRESSBLOCK__NSEC_STATUS__STAT_ALLCHIDLE__FIELD (0x1 << APB4SLVADDRESSBLOCK__NSEC_STATUS__STAT_ALLCHIDLE__SHIFT)
#define APB4SLVADDRESSBLOCK__NSEC_STATUS__STAT_ALLCHIDLE__M (0x1 << APB4SLVADDRESSBLOCK__NSEC_STATUS__STAT_ALLCHIDLE__SHIFT)
                
/* field: APB4SLVADDRESSBLOCK.NSEC_STATUS.STAT_ALLCHSTOPPED, pos: [18:18] -- All Non-Secure Channel Stopped Status. Set to '1' whenever all Non-secure DMA channels are in stopped or inactive state and the ALLCHSTOP request is active. Not set when channels reach the stopped state for other reasons. All Non-secure channels are forced to an immediate stopped state until ALLCHSTOP request is asserted even if they were enabled after the request. Cleared by writing '1' to this bit. The ALLCHSTOP request is also cleared when this bit is cleared.*/
#define APB4SLVADDRESSBLOCK__NSEC_STATUS__STAT_ALLCHSTOPPED__SHIFT 18
#define APB4SLVADDRESSBLOCK__NSEC_STATUS__STAT_ALLCHSTOPPED__FIELD (0x1 << APB4SLVADDRESSBLOCK__NSEC_STATUS__STAT_ALLCHSTOPPED__SHIFT)
