#define APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RESUMECMD__FIELD (0x1 << APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RESUMECMD__SHIFT)
#define APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RESUMECMD__M (0x1 << APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RESUMECMD__SHIFT)
                
