#define APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RAZWI_1__SHIFT 17
#define APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RAZWI_1__FIELD (0x7 << APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RAZWI_1__SHIFT)
                
