#define APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RAZWI_2__SHIFT 21
#define APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RAZWI_2__FIELD (0x7 << APB4SLVADDRESSBLOCK__DMACH1_CH_CMD__RAZWI_2__SHIFT)
                
