#define APB4SLVADDRESSBLOCK__DMACH1_CH_CTRL__RAZWI_0__FIELD (0x1 << APB4SLVADDRESSBLOCK__DMACH1_CH_CTRL__RAZWI_0__SHIFT)
#define APB4SLVADDRESSBLOCK__DMACH1_CH_CTRL__RAZWI_0__M (0x1 << APB4SLVADDRESSBLOCK__DMACH1_CH_CTRL__RAZWI_0__SHIFT)
                
