#define APB4SLVADDRESSBLOCK__DMACH1_CH_CTRL__CHPRIO__FIELD (0xf << APB4SLVADDRESSBLOCK__DMACH1_CH_CTRL__CHPRIO__SHIFT)
                
/* field: APB4SLVADDRESSBLOCK.DMACH1_CH_CTRL.RAZWI_1, pos: [8:8] -- Read-As-Zero, Writes Ignored.*/
