/* field: APB4SLVADDRESSBLOCK.DMACH1_CH_CTRL.USESRCTRIGIN, pos: [25:25] -- Enable Source Trigger Input use for this command.
- 0: disable
- 1: enable*/
#define APB4SLVADDRESSBLOCK__DMACH1_CH_CTRL__USESRCTRIGIN__SHIFT 25
