#define APB4SLVADDRESSBLOCK__DMACH1_CH_DESTRIGINCFG__RAZWI_0__FIELD (0xfffff << APB4SLVADDRESSBLOCK__DMACH1_CH_DESTRIGINCFG__RAZWI_0__SHIFT)
                
