#define BLOCK__PSTATE_REG__DAT_LINE_ACTIVE__SHIFT 2
#define BLOCK__PSTATE_REG__DAT_LINE_ACTIVE__FIELD (0x1 << BLOCK__PSTATE_REG__DAT_LINE_ACTIVE__SHIFT)
