#define BLOCK__HOST_CTRL1_R__EXT_DAT_XFER__SHIFT 5
#define BLOCK__HOST_CTRL1_R__EXT_DAT_XFER__FIELD (0x1 << BLOCK__HOST_CTRL1_R__EXT_DAT_XFER__SHIFT)
#define BLOCK__HOST_CTRL1_R__EXT_DAT_XFER_DEFAULT__E (0  << BLOCK__HOST_CTRL1_R__EXT_DAT_XFER__SHIFT)
#define BLOCK__HOST_CTRL1_R__EXT_DAT_XFER_EIGHT_BIT__E (1  << BLOCK__HOST_CTRL1_R__EXT_DAT_XFER__SHIFT)
#define BLOCK__HOST_CTRL1_R__EXT_DAT_XFER_EIGHT_BIT__M (1  << BLOCK__HOST_CTRL1_R__EXT_DAT_XFER__SHIFT)
                
/* field: BLOCK.HOST_CTRL1_R.CARD_DETECT_TEST_LVL, pos: [6:6] -- Card Detect Test Level

This bit is enabled while the Card Detect Signal Selection is set to 1 and it indicates whether a card inserted or not.*/
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_TEST_LVL__SHIFT 6
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_TEST_LVL__FIELD (0x1 << BLOCK__HOST_CTRL1_R__CARD_DETECT_TEST_LVL__SHIFT)
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_TEST_LVL_CARD_INSERTED__E (1  << BLOCK__HOST_CTRL1_R__CARD_DETECT_TEST_LVL__SHIFT)
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_TEST_LVL_CARD_INSERTED__M (1  << BLOCK__HOST_CTRL1_R__CARD_DETECT_TEST_LVL__SHIFT)
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_TEST_LVL_NO_CARD__E (0  << BLOCK__HOST_CTRL1_R__CARD_DETECT_TEST_LVL__SHIFT)
                
/* field: BLOCK.HOST_CTRL1_R.CARD_DETECT_SIG_SEL, pos: [7:7] -- Card Detect Signal Selection

This bit selects a source for card detection. When the source for the card detection is switched, the interrupt must be disabled during the switching period.*/
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_SIG_SEL__SHIFT 7
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_SIG_SEL__FIELD (0x1 << BLOCK__HOST_CTRL1_R__CARD_DETECT_SIG_SEL__SHIFT)
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_SIG_SEL_CARD_DT_TEST_LEVEL__E (1  << BLOCK__HOST_CTRL1_R__CARD_DETECT_SIG_SEL__SHIFT)
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_SIG_SEL_CARD_DT_TEST_LEVEL__M (1  << BLOCK__HOST_CTRL1_R__CARD_DETECT_SIG_SEL__SHIFT)
#define BLOCK__HOST_CTRL1_R__CARD_DETECT_SIG_SEL_SDCD_PIN__E (0  << BLOCK__HOST_CTRL1_R__CARD_DETECT_SIG_SEL__SHIFT)
                
//----------------------------------------------------------------------------
// register: BLOCK.PWR_CTRL_R
/* desc: This register is used to control the bus power for the Card. This register is applicable for an SD, eMMC, and UHS-II modes.*/
                
/* field: BLOCK.PWR_CTRL_R.SD_BUS_PWR_VDD1, pos: [0:0] -- SD Bus Power for VDD1

This bit enables VDD1 power of the card. This setting is available on the sd_vdd1_on output of DWC_mshc so that it can be used to control the VDD1 power supply of the card. Before setting this bit, the SD Host Driver sets the SD Bus Voltage Select bit. If the Host Controller detects a No Card state, this bit is cleared.

In SD mode, if this bit is cleared, the Host Controller stops the SD Clock by clearing the SD_CLK_IN bit in the CLK_CTRL_R register.*/
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD1__SHIFT 0
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD1__FIELD (0x1 << BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD1_OFF__E (0  << BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD1_ON__E (1  << BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD1_ON__M (1  << BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD1__SHIFT)
                
/* field: BLOCK.PWR_CTRL_R.SD_BUS_VOL_VDD1, pos: [3:1] -- SD Bus Voltage Select for VDD1/eMMC Bus Voltage Select for VDD

These bits enable the Host Driver to select the voltage level for an SD/eMMC card. Before setting this register, the Host Driver checks the Voltage Support bits in the Capabilities register.
If an unsupported voltage is selected, the Host System does not supply the SD Bus voltage. The value set in this field is available on the DWC_mshc output signal (sd_vdd1_sel), which is used by the voltage switching circuitry.

SD Bus Voltage Select options:
 - 0x7 : 3.3V(Typical)
 - 0x6 : 3.0V(Typical)
 - 0x5 : 1.8V(Typical) for Embedded
 - 0x4 : 0x0   - Reserved

eMMC Bus Voltage Select options:
 - 0x7 : 3.3V(Typical)
 - 0x6 : 1.8V(Typical)
 - 0x5 : 1.2V(Typical)
 - 0x4 : 0x0   - Reserved*/
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT 1
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__FIELD (0x7 << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1_RSVD0__E (0  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1_RSVD1__E (1  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1_RSVD2__E (2  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1_RSVD3__E (3  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1_RSVD4__E (4  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1_V_1_8__E (5  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1_V_3_0__E (6  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1_V_3_3__E (7  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD1__SHIFT)
                
/* field: BLOCK.PWR_CTRL_R.SD_BUS_PWR_VDD2, pos: [4:4] -- SD Bus Power for VDD2.
This is irrelevant for SD/eMMC card.*/
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD2__SHIFT 4
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD2__FIELD (0x1 << BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD2_OFF__E (0  << BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD2_ON__E (1  << BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD2_ON__M (1  << BLOCK__PWR_CTRL_R__SD_BUS_PWR_VDD2__SHIFT)
                
/* field: BLOCK.PWR_CTRL_R.SD_BUS_VOL_VDD2, pos: [7:5] -- SD Bus Voltage Select for VDD2.
This is irrelevant for SD/eMMC card.*/
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT 5
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__FIELD (0x7 << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2_NOT_USED6__E (6  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2_NOT_USED7__E (7  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2_NO_VDD2__E (0  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2_RSVD1__E (1  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2_RSVD2__E (2  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2_RSVD3__E (3  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2_V_1_2__E (4  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT)
#define BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2_V_1_8__E (5  << BLOCK__PWR_CTRL_R__SD_BUS_VOL_VDD2__SHIFT)
                
//----------------------------------------------------------------------------
// register: BLOCK.BGAP_CTRL_R
/* desc: This register is used by the host driver to control any operation related to Block Gap. This register is applicable for an SD/eMMC/UHS-II mode.*/
                
/* field: BLOCK.BGAP_CTRL_R.STOP_BG_REQ, pos: [0:0] -- Stop At Block Gap Request

This bit is used to stop executing read and write transactions at the next block gap for non-DMA, SDMA, and ADMA transfers.*/
#define BLOCK__BGAP_CTRL_R__STOP_BG_REQ__SHIFT 0
#define BLOCK__BGAP_CTRL_R__STOP_BG_REQ__FIELD (0x1 << BLOCK__BGAP_CTRL_R__STOP_BG_REQ__SHIFT)
#define BLOCK__BGAP_CTRL_R__STOP_BG_REQ_STOP__E (1  << BLOCK__BGAP_CTRL_R__STOP_BG_REQ__SHIFT)
#define BLOCK__BGAP_CTRL_R__STOP_BG_REQ_STOP__M (1  << BLOCK__BGAP_CTRL_R__STOP_BG_REQ__SHIFT)
#define BLOCK__BGAP_CTRL_R__STOP_BG_REQ_XFER__E (0  << BLOCK__BGAP_CTRL_R__STOP_BG_REQ__SHIFT)
                
/* field: BLOCK.BGAP_CTRL_R.CONTINUE_REQ, pos: [1:1] -- Continue Request

This bit is used to restart the transaction, which was stopped using the Stop At Block Gap Request. The Host Controller automatically clears this bit when the transaction restarts. If stop at block gap request is set to 1, any write to this bit is ignored.*/
#define BLOCK__BGAP_CTRL_R__CONTINUE_REQ__SHIFT 1
#define BLOCK__BGAP_CTRL_R__CONTINUE_REQ__FIELD (0x1 << BLOCK__BGAP_CTRL_R__CONTINUE_REQ__SHIFT)
#define BLOCK__BGAP_CTRL_R__CONTINUE_REQ_NO_AFFECT__E (0  << BLOCK__BGAP_CTRL_R__CONTINUE_REQ__SHIFT)
#define BLOCK__BGAP_CTRL_R__CONTINUE_REQ_RESTART__E (1  << BLOCK__BGAP_CTRL_R__CONTINUE_REQ__SHIFT)
#define BLOCK__BGAP_CTRL_R__CONTINUE_REQ_RESTART__M (1  << BLOCK__BGAP_CTRL_R__CONTINUE_REQ__SHIFT)
                
/* field: BLOCK.BGAP_CTRL_R.RD_WAIT_CTRL, pos: [2:2] -- Read Wait Control

This bit is used to enable the read wait protocol to stop read data using DAT[2] line if the card supports read wait. Otherwise, the Host Controller has to stop the card clock to hold the read data.*/
#define BLOCK__BGAP_CTRL_R__RD_WAIT_CTRL__SHIFT 2
#define BLOCK__BGAP_CTRL_R__RD_WAIT_CTRL__FIELD (0x1 << BLOCK__BGAP_CTRL_R__RD_WAIT_CTRL__SHIFT)
#define BLOCK__BGAP_CTRL_R__RD_WAIT_CTRL_DISABLE__E (0  << BLOCK__BGAP_CTRL_R__RD_WAIT_CTRL__SHIFT)
#define BLOCK__BGAP_CTRL_R__RD_WAIT_CTRL_ENABLE__E (1  << BLOCK__BGAP_CTRL_R__RD_WAIT_CTRL__SHIFT)
#define BLOCK__BGAP_CTRL_R__RD_WAIT_CTRL_ENABLE__M (1  << BLOCK__BGAP_CTRL_R__RD_WAIT_CTRL__SHIFT)
                
/* field: BLOCK.BGAP_CTRL_R.INT_AT_BGAP, pos: [3:3] -- Interrupt At Block Gap

This bit is valid only in the 4-bit mode of an SDIO card and is used to select a sample point in the interrupt cycle. Setting to 1 enables interrupt detection at the block gap for a multiple block transfer.*/
#define BLOCK__BGAP_CTRL_R__INT_AT_BGAP__SHIFT 3
#define BLOCK__BGAP_CTRL_R__INT_AT_BGAP__FIELD (0x1 << BLOCK__BGAP_CTRL_R__INT_AT_BGAP__SHIFT)
#define BLOCK__BGAP_CTRL_R__INT_AT_BGAP_DISABLE__E (0  << BLOCK__BGAP_CTRL_R__INT_AT_BGAP__SHIFT)
#define BLOCK__BGAP_CTRL_R__INT_AT_BGAP_ENABLE__E (1  << BLOCK__BGAP_CTRL_R__INT_AT_BGAP__SHIFT)
#define BLOCK__BGAP_CTRL_R__INT_AT_BGAP_ENABLE__M (1  << BLOCK__BGAP_CTRL_R__INT_AT_BGAP__SHIFT)
                
/* field: BLOCK.BGAP_CTRL_R.RSVD_7_4, pos: [7:4] -- These bits of the Block Gap Control register are reserved. They always return 0.*/
#define BLOCK__BGAP_CTRL_R__RSVD_7_4__SHIFT 4
#define BLOCK__BGAP_CTRL_R__RSVD_7_4__FIELD (0xf << BLOCK__BGAP_CTRL_R__RSVD_7_4__SHIFT)
                
//----------------------------------------------------------------------------
// register: BLOCK.WUP_CTRL_R
/* desc: This register is mandatory for the Host Controller, but the wakeup functionality depends on the Host Controller system hardware and software. The Host Driver maintains voltage on the SD Bus by
setting the SD Bus Power to 1 in the Power Control Register, while a wakeup event through the Card Interrupt is desired.*/
                
/* field: BLOCK.WUP_CTRL_R.CARD_INT, pos: [0:0] -- Wakeup Event Enable on Card Interrupt

This bit enables wakeup event through a Card Interrupt assertion in the Normal Interrupt Status register. This bit can be set to 1 if FN_WUS (Wake Up Support) in CIS is set to 1.*/
#define BLOCK__WUP_CTRL_R__CARD_INT__SHIFT 0
#define BLOCK__WUP_CTRL_R__CARD_INT__FIELD (0x1 << BLOCK__WUP_CTRL_R__CARD_INT__SHIFT)
#define BLOCK__WUP_CTRL_R__CARD_INT_DISABLED__E (0  << BLOCK__WUP_CTRL_R__CARD_INT__SHIFT)
#define BLOCK__WUP_CTRL_R__CARD_INT_ENABLED__E (1  << BLOCK__WUP_CTRL_R__CARD_INT__SHIFT)
#define BLOCK__WUP_CTRL_R__CARD_INT_ENABLED__M (1  << BLOCK__WUP_CTRL_R__CARD_INT__SHIFT)
                
/* field: BLOCK.WUP_CTRL_R.CARD_INSERT, pos: [1:1] -- Wakeup Event Enable on SD Card Insertion

This bit enables wakeup event through Card Insertion assertion in the Normal Interrupt Status register. FN_WUS (Wake Up Support) in CIS does not affect this bit.*/
#define BLOCK__WUP_CTRL_R__CARD_INSERT__SHIFT 1
#define BLOCK__WUP_CTRL_R__CARD_INSERT__FIELD (0x1 << BLOCK__WUP_CTRL_R__CARD_INSERT__SHIFT)
#define BLOCK__WUP_CTRL_R__CARD_INSERT_DISABLED__E (0  << BLOCK__WUP_CTRL_R__CARD_INSERT__SHIFT)
#define BLOCK__WUP_CTRL_R__CARD_INSERT_ENABLED__E (1  << BLOCK__WUP_CTRL_R__CARD_INSERT__SHIFT)
#define BLOCK__WUP_CTRL_R__CARD_INSERT_ENABLED__M (1  << BLOCK__WUP_CTRL_R__CARD_INSERT__SHIFT)
                
/* field: BLOCK.WUP_CTRL_R.CARD_REMOVAL, pos: [2:2] -- Wakeup Event Enable on SD Card Removal

This bit enables wakeup event through Card Removal assertion in the Normal Interrupt Status register. For the SDIO card, Wake Up Support (FN_WUS) in the Card Information Structure (CIS) register does not affect this bit.*/
#define BLOCK__WUP_CTRL_R__CARD_REMOVAL__SHIFT 2
#define BLOCK__WUP_CTRL_R__CARD_REMOVAL__FIELD (0x1 << BLOCK__WUP_CTRL_R__CARD_REMOVAL__SHIFT)
#define BLOCK__WUP_CTRL_R__CARD_REMOVAL_DISABLED__E (0  << BLOCK__WUP_CTRL_R__CARD_REMOVAL__SHIFT)
#define BLOCK__WUP_CTRL_R__CARD_REMOVAL_ENABLED__E (1  << BLOCK__WUP_CTRL_R__CARD_REMOVAL__SHIFT)
#define BLOCK__WUP_CTRL_R__CARD_REMOVAL_ENABLED__M (1  << BLOCK__WUP_CTRL_R__CARD_REMOVAL__SHIFT)
                
/* field: BLOCK.WUP_CTRL_R.RSVD_7_3, pos: [7:3] -- These bits of Wakeup Control register are reserved. They always return 0.*/
#define BLOCK__WUP_CTRL_R__RSVD_7_3__SHIFT 3
#define BLOCK__WUP_CTRL_R__RSVD_7_3__FIELD (0x1f << BLOCK__WUP_CTRL_R__RSVD_7_3__SHIFT)
                
//----------------------------------------------------------------------------
// register: BLOCK.CLK_CTRL_R
/* desc: This register controls SDCLK (card clock) in an SD/eMMC mode and RCLK in the UHS-II mode. This register is applicable for an SD/eMMC/UHS-II mode.*/
                
/* field: BLOCK.CLK_CTRL_R.INTERNAL_CLK_EN, pos: [0:0] -- Internal Clock Enable

This bit is set to 0 when the Host Driver is not using the Host Controller or the Host Controller awaits a wakeup interrupt. The Host Controller
must stop its internal clock to enter a very low power state. However, registers can still be read and written to. The value is reflected on the intclk_en signal.

Note: If this bit is not used to control the internal clock (base clock and manager clock), it is recommended to set this bit to '1' .*/
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_EN__SHIFT 0
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_EN__FIELD (0x1 << BLOCK__CLK_CTRL_R__INTERNAL_CLK_EN__SHIFT)
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_EN_FALSE__E (0  << BLOCK__CLK_CTRL_R__INTERNAL_CLK_EN__SHIFT)
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_EN_TRUE__E (1  << BLOCK__CLK_CTRL_R__INTERNAL_CLK_EN__SHIFT)
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_EN_TRUE__M (1  << BLOCK__CLK_CTRL_R__INTERNAL_CLK_EN__SHIFT)
                
/* field: BLOCK.CLK_CTRL_R.INTERNAL_CLK_STABLE, pos: [1:1] -- Internal Clock Stable

This bit enables the Host Driver to check the clock stability twice after the Internal Clock Enable bit is set and after the PLL Enable bit is set.
This bit reflects the synchronized value of the intclk_stable signal after the Internal Clock Enable bit is set to 1 and also reflects
the synchronized value of the card_clk_stable signal after the PLL Enable bit is set to 1.*/
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_STABLE__SHIFT 1
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_STABLE__FIELD (0x1 << BLOCK__CLK_CTRL_R__INTERNAL_CLK_STABLE__SHIFT)
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_STABLE_FALSE__E (0  << BLOCK__CLK_CTRL_R__INTERNAL_CLK_STABLE__SHIFT)
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_STABLE_TRUE__E (1  << BLOCK__CLK_CTRL_R__INTERNAL_CLK_STABLE__SHIFT)
#define BLOCK__CLK_CTRL_R__INTERNAL_CLK_STABLE_TRUE__M (1  << BLOCK__CLK_CTRL_R__INTERNAL_CLK_STABLE__SHIFT)
                
/* field: BLOCK.CLK_CTRL_R.SD_CLK_EN, pos: [2:2] -- SD/eMMC Clock Enable

This bit stops the SDCLK or RCLK when set to 0. The SDCLK/RCLK Frequency Select bit can be changed when this bit is set to 0.
The value is reflected on the clk2card_on pin.*/
#define BLOCK__CLK_CTRL_R__SD_CLK_EN__SHIFT 2
#define BLOCK__CLK_CTRL_R__SD_CLK_EN__FIELD (0x1 << BLOCK__CLK_CTRL_R__SD_CLK_EN__SHIFT)
#define BLOCK__CLK_CTRL_R__SD_CLK_EN_FALSE__E (0  << BLOCK__CLK_CTRL_R__SD_CLK_EN__SHIFT)
#define BLOCK__CLK_CTRL_R__SD_CLK_EN_TRUE__E (1  << BLOCK__CLK_CTRL_R__SD_CLK_EN__SHIFT)
#define BLOCK__CLK_CTRL_R__SD_CLK_EN_TRUE__M (1  << BLOCK__CLK_CTRL_R__SD_CLK_EN__SHIFT)
                
/* field: BLOCK.CLK_CTRL_R.PLL_ENABLE, pos: [3:3] -- PLL Enable

This bit is used to activate the PLL (applicable when Host Version 4 Enable = 1). When Host Version 4 Enable = 0, INTERNAL_CLK_EN bit may be used to activate PLL. The value is reflected on the card_clk_en signal.

Note: If this bit is not used to to active the PLL when Host Version 4 Enable = 1, it is recommended to set this bit to '1' .*/
#define BLOCK__CLK_CTRL_R__PLL_ENABLE__SHIFT 3
#define BLOCK__CLK_CTRL_R__PLL_ENABLE__FIELD (0x1 << BLOCK__CLK_CTRL_R__PLL_ENABLE__SHIFT)
#define BLOCK__CLK_CTRL_R__PLL_ENABLE_FALSE__E (0  << BLOCK__CLK_CTRL_R__PLL_ENABLE__SHIFT)
#define BLOCK__CLK_CTRL_R__PLL_ENABLE_TRUE__E (1  << BLOCK__CLK_CTRL_R__PLL_ENABLE__SHIFT)
#define BLOCK__CLK_CTRL_R__PLL_ENABLE_TRUE__M (1  << BLOCK__CLK_CTRL_R__PLL_ENABLE__SHIFT)
                
/* field: BLOCK.CLK_CTRL_R.RSVD_4, pos: [4:4] -- This bit of the CLK_CTRL_R register is reserved. It always returns 0.*/
#define BLOCK__CLK_CTRL_R__RSVD_4__SHIFT 4
#define BLOCK__CLK_CTRL_R__RSVD_4__FIELD (0x1 << BLOCK__CLK_CTRL_R__RSVD_4__SHIFT)
#define BLOCK__CLK_CTRL_R__RSVD_4__M (0x1 << BLOCK__CLK_CTRL_R__RSVD_4__SHIFT)
                
/* field: BLOCK.CLK_CTRL_R.CLK_GEN_SELECT, pos: [5:5] -- Clock Generator Select

This bit is used to select the clock generator mode in SDCLK/RCLK Frequency Select. If Preset Value Enable = 0, this bit is set by the Host Driver. If Preset Value Enable = 1, this bit is
automatically set to a value specified in one of the Preset Value registers. The value is reflected on the card_clk_gen_sel signal.*/
#define BLOCK__CLK_CTRL_R__CLK_GEN_SELECT__SHIFT 5
#define BLOCK__CLK_CTRL_R__CLK_GEN_SELECT__FIELD (0x1 << BLOCK__CLK_CTRL_R__CLK_GEN_SELECT__SHIFT)
#define BLOCK__CLK_CTRL_R__CLK_GEN_SELECT_FALSE__E (0  << BLOCK__CLK_CTRL_R__CLK_GEN_SELECT__SHIFT)
#define BLOCK__CLK_CTRL_R__CLK_GEN_SELECT_TRUE__E (1  << BLOCK__CLK_CTRL_R__CLK_GEN_SELECT__SHIFT)
#define BLOCK__CLK_CTRL_R__CLK_GEN_SELECT_TRUE__M (1  << BLOCK__CLK_CTRL_R__CLK_GEN_SELECT__SHIFT)
                
/* field: BLOCK.CLK_CTRL_R.UPPER_FREQ_SEL, pos: [7:6] -- These bits specify the upper 2 bits of 10-bit SDCLK/RCLK Frequency Select control. The value is reflected on the upper 2 bits of the card_clk_freq_sel signal.*/
#define BLOCK__CLK_CTRL_R__UPPER_FREQ_SEL__SHIFT 6
#define BLOCK__CLK_CTRL_R__UPPER_FREQ_SEL__FIELD (0x3 << BLOCK__CLK_CTRL_R__UPPER_FREQ_SEL__SHIFT)
                
/* field: BLOCK.CLK_CTRL_R.FREQ_SEL, pos: [15:8] -- SDCLK/RCLK Frequency Select

These bits are used to select the frequency of the SDCLK signal. These bits depend on setting of Preset Value Enable in the Host Control 2 register. If Preset Value Enable = 0, these bits are set by
the Host
Driver. If Preset Value Enable = 1, these bits are automatically set to a value specified in one of the Preset Value register. The value is reflected on the lower 8-bit of the card_clk_freq_sel
signal.



10-bit Divided Clock Mode:
 - 0x3FF : 1/2046 Divided clock
 - ..........
 - N    : 1/2N Divided Clock
 - ..........
 - 0x002  : 1/4 Divided Clock
 - 0x001 : 1/2 Divided Clock
 - 0x000 : Base clock (10MHz - 255 MHz)



Programmable Clock Mode : Enables the Host System to select a fine grain SD clock frequency:
 - 0x3FF : Base clock  * M /1024
 - ..........
 - N-1  : Base clock  * M /N
 - ..........
 - 0x002  : Base clock  * M /3
 - 0x001 : Base clock  * M /2
 - 0x000 : Base clock  * M*/
#define BLOCK__CLK_CTRL_R__FREQ_SEL__SHIFT 8
#define BLOCK__CLK_CTRL_R__FREQ_SEL__FIELD (0xff << BLOCK__CLK_CTRL_R__FREQ_SEL__SHIFT)
                
//----------------------------------------------------------------------------
// register: BLOCK.TOUT_CTRL_R
/* desc: This register is used to set the Data Timeout Counter value for an SD/eMMC mode according to the timer clock defined by the Capabilities register, while
initializig the Host Controller.*/
                
/* field: BLOCK.TOUT_CTRL_R.TOUT_CNT, pos: [3:0] -- Data Timeout Counter Value.

This value determines the interval by which DAT line timeouts are detected. The Timeout clock frequency is generated by dividing the base clock TMCLK value by this value. When setting this
register, prevent inadvertent timeout events by clearing the Data Timeout Error Status Enable (in the Error Interrupt Status Enable register).
The values for these bits are:
 - 0xF :  Reserved
 - 0xE : TMCLK x 2^27
 - .........
 - 0x1 : TMCLK x 2^14
 - 0x0 : TMCLK x 2^13

Note: During a boot operating in an eMMC mode, an application must configure the boot data timeout value (approximately 1 sec) in this bit.*/
#define BLOCK__TOUT_CTRL_R__TOUT_CNT__SHIFT 0
#define BLOCK__TOUT_CTRL_R__TOUT_CNT__FIELD (0xf << BLOCK__TOUT_CTRL_R__TOUT_CNT__SHIFT)
                
/* field: BLOCK.TOUT_CTRL_R.RSVD_7_4, pos: [7:4] -- These bits of the Timeout Control register are reserved. They always return 0.*/
#define BLOCK__TOUT_CTRL_R__RSVD_7_4__SHIFT 4
#define BLOCK__TOUT_CTRL_R__RSVD_7_4__FIELD (0xf << BLOCK__TOUT_CTRL_R__RSVD_7_4__SHIFT)
                
//----------------------------------------------------------------------------
// register: BLOCK.SW_RST_R
/* desc: This register is used to generate a reset pulse by writing 1 to each bit of this register. After completing the reset, the Host Controller clears each bit. As it takes some time to complete a software reset, the Host Driver confirms that these bits are 0. This register is applicable for an SD/eMMC/UHS-II mode.

Note: Refer Software Reset section in the DWC_mshc Databook for additional details.*/
                
/* field: BLOCK.SW_RST_R.SW_RST_ALL, pos: [0:0] -- Software Reset For All
This reset affects the entire Host Controller except for the card detection circuit. During its initialization, the Host Driver sets this bit to 1 to reset the Host Controller. All registers are reset except the capabilities register. If this bit is set to 1, the Host Driver must issue reset command and reinitialize the card.*/
#define BLOCK__SW_RST_R__SW_RST_ALL__SHIFT 0
#define BLOCK__SW_RST_R__SW_RST_ALL__FIELD (0x1 << BLOCK__SW_RST_R__SW_RST_ALL__SHIFT)
#define BLOCK__SW_RST_R__SW_RST_ALL_FALSE__E (0  << BLOCK__SW_RST_R__SW_RST_ALL__SHIFT)
#define BLOCK__SW_RST_R__SW_RST_ALL_TRUE__E (1  << BLOCK__SW_RST_R__SW_RST_ALL__SHIFT)
#define BLOCK__SW_RST_R__SW_RST_ALL_TRUE__M (1  << BLOCK__SW_RST_R__SW_RST_ALL__SHIFT)
                
/* field: BLOCK.SW_RST_R.SW_RST_CMD, pos: [1:1] -- Software Reset For CMD line

This bit resets only a part of the command circuit to be able to issue a command.  This reset is effective only for a command issuing circuit (including response error statuses related to Command Inhibit (CMD) control) and does not affect the data transfer circuit. Host Controller can continue data transfer even after this reset is executed while handling subcommand-response errors.

The following registers and bits are cleared by this bit:
 - Present State register : Command Inhibit (CMD) bit
 - Normal Interrupt Status register : Command Complete bit
 - Error Interrupt Status : Response error statuses related to Command Inhibit (CMD) bit*/
#define BLOCK__SW_RST_R__SW_RST_CMD__SHIFT 1
#define BLOCK__SW_RST_R__SW_RST_CMD__FIELD (0x1 << BLOCK__SW_RST_R__SW_RST_CMD__SHIFT)
#define BLOCK__SW_RST_R__SW_RST_CMD_FALSE__E (0  << BLOCK__SW_RST_R__SW_RST_CMD__SHIFT)
#define BLOCK__SW_RST_R__SW_RST_CMD_TRUE__E (1  << BLOCK__SW_RST_R__SW_RST_CMD__SHIFT)
#define BLOCK__SW_RST_R__SW_RST_CMD_TRUE__M (1  << BLOCK__SW_RST_R__SW_RST_CMD__SHIFT)
                
/* field: BLOCK.SW_RST_R.SW_RST_DAT, pos: [2:2] -- Software Reset For DAT line


This bit is used in SD/eMMC mode and it resets only a part of the data circuit and the DMA circuit is also reset.

The following registers and bits are cleared by this bit:
 - Buffer Data Port register
 -- Buffer is cleared and initialized.
 - Present state register
 -- Buffer Read Enable
 -- Buffer Write Enable
 -- Read Transfer Active
 -- Write Transfer Active
 -- DAT Line Active
 -- Command Inhibit (DAT)
 - Block Gap Control register
 -- Continue Request
 -- Stop At Block Gap Request
 - Normal Interrupt status register
 -- Buffer Read Ready
 -- Buffer Write Ready
 -- DMA Interrupt
 -- Block Gap Event
 -- Transfer Complete*/
#define BLOCK__SW_RST_R__SW_RST_DAT__SHIFT 2
#define BLOCK__SW_RST_R__SW_RST_DAT__FIELD (0x1 << BLOCK__SW_RST_R__SW_RST_DAT__SHIFT)
#define BLOCK__SW_RST_R__SW_RST_DAT_FALSE__E (0  << BLOCK__SW_RST_R__SW_RST_DAT__SHIFT)
#define BLOCK__SW_RST_R__SW_RST_DAT_TRUE__E (1  << BLOCK__SW_RST_R__SW_RST_DAT__SHIFT)
#define BLOCK__SW_RST_R__SW_RST_DAT_TRUE__M (1  << BLOCK__SW_RST_R__SW_RST_DAT__SHIFT)
                
/* field: BLOCK.SW_RST_R.RSVD_7_3, pos: [7:3] -- These bits of the SW_RST_R register are reserved. They always return 0.*/
#define BLOCK__SW_RST_R__RSVD_7_3__SHIFT 3
#define BLOCK__SW_RST_R__RSVD_7_3__FIELD (0x1f << BLOCK__SW_RST_R__RSVD_7_3__SHIFT)
                
