#define BLOCK__HOST_CTRL2_R__UHS_MODE_SEL_RSVD5__E (5  << BLOCK__HOST_CTRL2_R__UHS_MODE_SEL__SHIFT)
#define BLOCK__HOST_CTRL2_R__UHS_MODE_SEL_RSVD6__E (6  << BLOCK__HOST_CTRL2_R__UHS_MODE_SEL__SHIFT)
#define BLOCK__HOST_CTRL2_R__UHS_MODE_SEL_SDR104__E (3  << BLOCK__HOST_CTRL2_R__UHS_MODE_SEL__SHIFT)
