#define BLOCK__HOST_CTRL2_R__HOST_VER4_ENABLE_TRUE__E (1  << BLOCK__HOST_CTRL2_R__HOST_VER4_ENABLE__SHIFT)
#define BLOCK__HOST_CTRL2_R__HOST_VER4_ENABLE_TRUE__M (1  << BLOCK__HOST_CTRL2_R__HOST_VER4_ENABLE__SHIFT)
                
