#define VENDOR2_BLOCK__CQCTL__CLR_ALL_TASKS__SHIFT 8
#define VENDOR2_BLOCK__CQCTL__CLR_ALL_TASKS__FIELD (0x1 << VENDOR2_BLOCK__CQCTL__CLR_ALL_TASKS__SHIFT)
