#define VENDOR2_BLOCK__CQISE__RED_STE_INT_STS_ENABLE__M (1  << VENDOR2_BLOCK__CQISE__RED_STE__SHIFT)
                
/* field: VENDOR2_BLOCK.CQISE.TCL_STE, pos: [3:3] -- Task cleared interrupt status enable*/
#define VENDOR2_BLOCK__CQISE__TCL_STE__SHIFT 3
