// register: TSN_SW_REG.MDIO_CFG
/* desc: MDIO Configuration register*/
                
/* field: TSN_SW_REG.MDIO_CFG.MDC_CLKDIV, pos: [7:0] -- Clock Divider to configure MDC clock frequency. Refer to 10.1 Clock Divider for more details.*/
#define TSN_SW_REG__MDIO_CFG__MDC_CLKDIV__SHIFT 0
#define TSN_SW_REG__MDIO_CFG__MDC_CLKDIV__FIELD (0xff << TSN_SW_REG__MDIO_CFG__MDC_CLKDIV__SHIFT)
                
/* field: TSN_SW_REG.MDIO_CFG.ENABLE, pos: [8:8] -- Enable the MDIO controller. If the controller is enabled then MDC will be toggled. 
ENABLE can only be read as 1 if a valid MDC_CLKDIV value is set.*/
#define TSN_SW_REG__MDIO_CFG__ENABLE__SHIFT 8
#define TSN_SW_REG__MDIO_CFG__ENABLE__FIELD (0x1 << TSN_SW_REG__MDIO_CFG__ENABLE__SHIFT)
#define TSN_SW_REG__MDIO_CFG__ENABLE__M (0x1 << TSN_SW_REG__MDIO_CFG__ENABLE__SHIFT)
                
/* field: TSN_SW_REG.MDIO_CFG.NPRE, pos: [15:15] -- No Preamble
With NPRE=1 the preamble generation is suppressed and frames are initiated with
Start of Frame pattern directly. Suitable in case that all connected PHYs accept
management frames without a preamble pattern. Recommended to be used if only
one PHY is connected.*/
#define TSN_SW_REG__MDIO_CFG__NPRE__SHIFT 15
#define TSN_SW_REG__MDIO_CFG__NPRE__FIELD (0x1 << TSN_SW_REG__MDIO_CFG__NPRE__SHIFT)
#define TSN_SW_REG__MDIO_CFG__NPRE__M (0x1 << TSN_SW_REG__MDIO_CFG__NPRE__SHIFT)
                
//----------------------------------------------------------------------------
// register: TSN_SW_REG.MDIO_CTRL
/* desc: MDIO Control register*/
                
/* field: TSN_SW_REG.MDIO_CTRL.READY, pos: [0:0] -- READY=1 indicates a finished transfer and also shows that the controller is ready for a
new transfer. READY=1 is only possible if ENABLE=1.
If READY=1 is signaled after a read transfer, then RD_DATA is valid until a new
transfer is started.*/
#define TSN_SW_REG__MDIO_CTRL__READY__SHIFT 0
#define TSN_SW_REG__MDIO_CTRL__READY__FIELD (0x1 << TSN_SW_REG__MDIO_CTRL__READY__SHIFT)
#define TSN_SW_REG__MDIO_CTRL__READY__M (0x1 << TSN_SW_REG__MDIO_CTRL__READY__SHIFT)
                
/* field: TSN_SW_REG.MDIO_CTRL.INIT, pos: [8:8] -- INIT=1 results in a MDIO write/read transfer if READY=1. If READY=0 while a
transfer is already pending or if ENABLE=0 then settings INIT=1 has no effect and
the current transaction is withdrawn.*/
#define TSN_SW_REG__MDIO_CTRL__INIT__SHIFT 8
#define TSN_SW_REG__MDIO_CTRL__INIT__FIELD (0x1 << TSN_SW_REG__MDIO_CTRL__INIT__SHIFT)
#define TSN_SW_REG__MDIO_CTRL__INIT__M (0x1 << TSN_SW_REG__MDIO_CTRL__INIT__SHIFT)
                
/* field: TSN_SW_REG.MDIO_CTRL.REGAD, pos: [20:16] -- MODE=0
Management Frame Register Address.
MODE=1
Management Frame Device (MMD) Address*/
#define TSN_SW_REG__MDIO_CTRL__REGAD__SHIFT 16
#define TSN_SW_REG__MDIO_CTRL__REGAD__FIELD (0x1f << TSN_SW_REG__MDIO_CTRL__REGAD__SHIFT)
                
/* field: TSN_SW_REG.MDIO_CTRL.MODE, pos: [21:21] -- Switch the MDIO frame format between clause 22 and clause 45 devices.
0 – clause 22 (typical for 10/100/1000 PHYs)
1 – clause 45*/
#define TSN_SW_REG__MDIO_CTRL__MODE__SHIFT 21
#define TSN_SW_REG__MDIO_CTRL__MODE__FIELD (0x1 << TSN_SW_REG__MDIO_CTRL__MODE__SHIFT)
#define TSN_SW_REG__MDIO_CTRL__MODE__M (0x1 << TSN_SW_REG__MDIO_CTRL__MODE__SHIFT)
                
/* field: TSN_SW_REG.MDIO_CTRL.PHYAD, pos: [28:24] -- Management Frame PHY Address.*/
#define TSN_SW_REG__MDIO_CTRL__PHYAD__SHIFT 24
#define TSN_SW_REG__MDIO_CTRL__PHYAD__FIELD (0x1f << TSN_SW_REG__MDIO_CTRL__PHYAD__SHIFT)
                
/* field: TSN_SW_REG.MDIO_CTRL.OP, pos: [31:30] -- Opcode to determine transfer type
If the frame format is based on Clause 22 MDIO (MODE=0)
01 – Write Access
10 – Read Access
If the frame format is based on Clause 45 MDIO (MODE=1)
00 – Address Write Access on the address register
01 – Write Access at the address register location (MMD register bank)
11 – Read Access at the address register location (MMD register bank)
10 – Read Access at the address register location (MMD register bank) and increment
address register after read.*/
#define TSN_SW_REG__MDIO_CTRL__OP__SHIFT 30
#define TSN_SW_REG__MDIO_CTRL__OP__FIELD (0x3 << TSN_SW_REG__MDIO_CTRL__OP__SHIFT)
                
