/* field: TSN_SW_REG.MDIO_RD_DATA.READ_DATA_1, pos: [7:0] -- Read Data is available if READY=1 after a transfer has been started. RD_DATA
represents the content of the management data field of the read transfer.*/
#define TSN_SW_REG__MDIO_RD_DATA__READ_DATA_1__SHIFT 0
#define TSN_SW_REG__MDIO_RD_DATA__READ_DATA_1__FIELD (0xff << TSN_SW_REG__MDIO_RD_DATA__READ_DATA_1__SHIFT)
                
/* field: TSN_SW_REG.MDIO_RD_DATA.READ_DATA_2, pos: [15:8] -- Read Data is available if READY=1 after a transfer has been started. RD_DATA
represents the content of the management data field of the read transfer.*/
#define TSN_SW_REG__MDIO_RD_DATA__READ_DATA_2__SHIFT 8
