#define TSN_SW_REG__MDIO_WR_DATA__WRITE_DATA_1__SHIFT 0
#define TSN_SW_REG__MDIO_WR_DATA__WRITE_DATA_1__FIELD (0xff << TSN_SW_REG__MDIO_WR_DATA__WRITE_DATA_1__SHIFT)
                
/* field: TSN_SW_REG.MDIO_WR_DATA.WRITE_DATA_2, pos: [15:8] -- Data is used for the management data field after a write transfer has been started.*/
#define TSN_SW_REG__MDIO_WR_DATA__WRITE_DATA_2__SHIFT 8
