/* field: DWC_DDRPHYA_ANIB2_P0.ATXSLEWRATE.ATXPREN, pos: [7:4] -- 4 bit binary trim for the driver pull-down slew rate. 4'b0000 has a slower slew rate than 4'b1111*/
#define DWC_DDRPHYA_ANIB2_P0__ATXSLEWRATE__ATXPREN__SHIFT 4
#define DWC_DDRPHYA_ANIB2_P0__ATXSLEWRATE__ATXPREN__FIELD (0xf << DWC_DDRPHYA_ANIB2_P0__ATXSLEWRATE__ATXPREN__SHIFT)
                
/* field: DWC_DDRPHYA_ANIB2_P0.ATXSLEWRATE.ATXPREDRVMODE, pos: [10:8] -- Controls predrivers to adjust timing of turn-on and turn-off of pull-up and pull-down segments.
- Recommended settings if the ANIB drives CK pins:
-- DDR3 = 3'b000
-- DDR4 = 3'b000
-- LPDDR3 = 3'b000
-- LPDDR4 = 3'b001
- Recommended settings if the ANIB does not drive CK pins:
-- DDR3 = 3'b011
-- DDR4 = 3'b011
-- LPDDR3 = 3'b011
-- LPDDR4 = 3'b001*/
#define DWC_DDRPHYA_ANIB2_P0__ATXSLEWRATE__ATXPREDRVMODE__SHIFT 8
#define DWC_DDRPHYA_ANIB2_P0__ATXSLEWRATE__ATXPREDRVMODE__FIELD (0x7 << DWC_DDRPHYA_ANIB2_P0__ATXSLEWRATE__ATXPREDRVMODE__SHIFT)
                
