#define DWC_DDRPHYA_DBYTE0_P0__DQDQSRCVCNTRL1__POWERDOWNRCVR__FIELD (0x1ff << DWC_DDRPHYA_DBYTE0_P0__DQDQSRCVCNTRL1__POWERDOWNRCVR__SHIFT)
                
