#define DWC_DDRPHYA_DBYTE0_P0__DQDQSRCVCNTRL1__RXPADSTANDBYEN__M (0x1 << DWC_DDRPHYA_DBYTE0_P0__DQDQSRCVCNTRL1__RXPADSTANDBYEN__SHIFT)
                
