//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_DBYTE1_P0.RXFIFOVISIBILITY
/* desc: Allows the contents of the data rx fifo to be read
via CSRs RxFifoContentsDBI,RxFifoContentsDQ7654,RxFifoContentsDQ3210.
The fifo must be quiescent, i.e. no actual operations in progress,
while reading the fifo. That is, the read from the RxFifo must be
after the max-read-latency (DFIMRL) time.

Procedure to read the contents of the entire RxFifo:
 - wait for any outstanding reads to complete (min 2*DFIMRL MemClks)
 - read and store RxFifoWrLoc[3:0] and RxFifoWrLocU[3:0] (they should be equal).
 - perform four BL8 memory reads
 - wait at least 2*DFIMRL MemClks.
 - for (iNib=0, iNib<8, iNib++)
 - [
 - 1. myRdPtr[2:0] = (stored RxFifoWrLoc[3:0]>>1) + iNib (may wrap 7 to 0)
 - 2. write addr=RxFifoVisibility, data=[csrRxFifoRdEn=0,csrFifoRdPtrOvr=1,csrRxFifoRdPtr=myRdPtr]
 - 3. write addr=RxFifoVisibility, data=[csrRxFifoRdEn=1,csrFifoRdPtrOvr=1,csrRxFifoRdPtr=myRdPtr]
 - 4. write addr=RxFifoVisibility, data=[csrRxFifoRdEn=0,csrFifoRdPtrOvr=1,csrRxFifoRdPtr=myRdPtr]
 - 5. wait for 8 DfiClk.
 - 6. read addr=RxFifoContentsDBI
 - 7. read addr=RxFifoContentsDQ7654
 - 8. read addr=RxFifoContentsDQ3210
 - 9. unpack/align resulting data as described in descriptions of RxFifoContents registers, and map according to the configuration of the csr Dq<7..0>LnSel[2:0].
 - ]
 - evaluate/compare with data that travels through normal read path (dfi_read_data_dbi,dfi_read_data).
 - write [csrRxFifoRdEn=0,csrFifoRdPtrOvr=0,csrRxFifoRdPtr = 0]
 - PHY is now available for normal mission-mode operation.  end of Procedure*/
                
/* field: DWC_DDRPHYA_DBYTE1_P0.RXFIFOVISIBILITY.RXFIFORDPTR, pos: [2:0] -- If CSR RxFifoRdPtrOVr is set, then this CSR selects
the rxfifo entry is visible in CSR.
This 3b field addresses 4b units of the 8x4b (32entry) fifo;
that is, rdfifo_nibble_address[2:0]=csrRxFifoRdPtr[2:0]

For example, Register RxFifoRdPtr[2:0]=2 will enable reading bit-entries 11..8.
The exact location of read data will depend on the prior history of reads
and PHY initialization.*/
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDPTR__SHIFT 0
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDPTR__FIELD (0x7 << DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDPTR__SHIFT)
                
/* field: DWC_DDRPHYA_DBYTE1_P0.RXFIFOVISIBILITY.RXFIFORDPTROVR, pos: [3:3] -- This field is programmable as follows:
- 0 : Normal operation - mission mode read pointer is enabled
- 1 : Override - Control of the rx fifo read pointer is ceded to CSR RxFifoRdPtr.*/
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDPTROVR__SHIFT 3
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDPTROVR__FIELD (0x1 << DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDPTROVR__SHIFT)
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDPTROVR__M (0x1 << DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDPTROVR__SHIFT)
                
/* field: DWC_DDRPHYA_DBYTE1_P0.RXFIFOVISIBILITY.RXFIFORDEN, pos: [4:4] -- Pulse [set 0-->1-->0] this bit to capture the Fifo Contents.*/
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDEN__SHIFT 4
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDEN__FIELD (0x1 << DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDEN__SHIFT)
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDEN__M (0x1 << DWC_DDRPHYA_DBYTE1_P0__RXFIFOVISIBILITY__RXFIFORDEN__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_DBYTE1_P0.RXFIFOCONTENTSDQ3210
/* desc: RX FIFO contents, lane[3:0]*/
                
/* field: DWC_DDRPHYA_DBYTE1_P0.RXFIFOCONTENTSDQ3210.RXFIFOCONTENTSDQ3210, pos: [15:0] -- A window into the contents of the RxFifo, as controlled by CSR RxFifoVisibility.
This register reads 4b at a time from lane0..3
from the four fifo entries addressed by rdfifo_nibble_address[2:0]=RxFifoRdPtr[2:0] Register
 - [15:12] = [lane3_ui3,lane3_ui2,lane3_ui1,lane3_ui0] where ui0 is the first occurring bit
 - [11: 8] = [lane2_ui3,lane2_ui2,lane2_ui1,lane2_ui0]
 - [ 7: 4] = [lane1_ui3,lane1_ui2,lane1_ui1,lane1_ui0]
 - [ 3: 0] = [lane0_ui3,lane0_ui2,lane0_ui1,lane0_ui0]

Note: The DBYTE lane of a given index is not the same as a memory DQ of the same index
unless the csr Dq<7..0>LnSel[2:0] have their default/reset value.*/
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOCONTENTSDQ3210__RXFIFOCONTENTSDQ3210__SHIFT 0
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOCONTENTSDQ3210__RXFIFOCONTENTSDQ3210__FIELD (0xffff << DWC_DDRPHYA_DBYTE1_P0__RXFIFOCONTENTSDQ3210__RXFIFOCONTENTSDQ3210__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_DBYTE1_P0.RXFIFOCONTENTSDQ7654
/* desc: RX FIFO contents, lane[7:4]*/
                
/* field: DWC_DDRPHYA_DBYTE1_P0.RXFIFOCONTENTSDQ7654.RXFIFOCONTENTSDQ7654, pos: [15:0] -- A window into the contents of the RxFifo, as controlled by CSR RxFifoVisibility.
This register reads 4b at a time from lane4..7
from the four fifo entries addressed by rdfifo_nibble_address[2:0]=RxFifoRdPtr[2:0] Register
 - [15:12] = [lane7_ui3,lane7_ui2,lane7_ui1,lane7_ui0]
 - [11: 8] = [lane6_ui3,lane6_ui2,lane6_ui1,lane6_ui0]
 - [ 7: 4] = [lane5_ui3,lane5_ui2,lane5_ui1,lane5_ui0]
 - [ 3: 0] = [lane4_ui3,lane4_ui2,lane4_ui1,lane4_ui0]

Note that the DBYTE lane of a given index is not the same as a memory DQ of the same index
unless the csr Dq<7..0>LnSel[2:0] have their default/reset value.*/
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOCONTENTSDQ7654__RXFIFOCONTENTSDQ7654__SHIFT 0
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOCONTENTSDQ7654__RXFIFOCONTENTSDQ7654__FIELD (0xffff << DWC_DDRPHYA_DBYTE1_P0__RXFIFOCONTENTSDQ7654__RXFIFOCONTENTSDQ7654__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_DBYTE1_P0.RXFIFOCONTENTSDBI
/* desc: RX FIFO contents, dbi*/
                
/* field: DWC_DDRPHYA_DBYTE1_P0.RXFIFOCONTENTSDBI.RXFIFOCONTENTSDBI, pos: [3:0] -- A window into the contents of the RxFifo, as controlled by CSR RxFifoVisibility.
This register reads 4b at a time from DBI
from the four fifo entries addressed by rdfifo_nibble_address[2:0]=RxFifoRdPtr[2:0] Register
[ 3: 0] = [dbi_ui3,dbi_ui2,dbi_ui1,dbi_ui0]

Note that the DBYTE DBI lane is the same as the memory DBI; it is not subject to mapping
using csr Dq<7..0>LnSel[2:0] as the DQ are.*/
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOCONTENTSDBI__RXFIFOCONTENTSDBI__SHIFT 0
#define DWC_DDRPHYA_DBYTE1_P0__RXFIFOCONTENTSDBI__RXFIFOCONTENTSDBI__FIELD (0xf << DWC_DDRPHYA_DBYTE1_P0__RXFIFOCONTENTSDBI__RXFIFOCONTENTSDBI__SHIFT)
                
