#define DWC_DDRPHYA_DBYTE1_P0__RXPBDLYTG1_R0__RXPBDLYTG1_R0__FIELD (0x7f << DWC_DDRPHYA_DBYTE1_P0__RXPBDLYTG1_R0__RXPBDLYTG1_R0__SHIFT)
                
