#define DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALCMPTRRESTRIM__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALCMPTRRESTRIM__SHIFT)
