/* field: DWC_DDRPHYA_MASTER0_P0.CALMISC2.CALCANCELROUNDERRDIS, pos: [13:13] -- The PEXT calibration result and NINT calibration results
naturally include a rounding error which manifests as
a change of impedance at the pad.
Where both of these errors are in the same direction the.
PEXT calibration result will be adjusted by 1 to offset.
NINT error.
Setting this csr to 1 prevents this adjustment.*/
#define DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALCANCELROUNDERRDIS__SHIFT 13
#define DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALCANCELROUNDERRDIS__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALCANCELROUNDERRDIS__SHIFT)
#define DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALCANCELROUNDERRDIS__M (0x1 << DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALCANCELROUNDERRDIS__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P0.CALMISC2.CALSLOWCMPANA, pos: [14:14] -- When set, this CSR doubles the time allowed for the analog comparator cell to
settle before sampling begins.*/
#define DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALSLOWCMPANA__SHIFT 14
#define DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALSLOWCMPANA__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P0__CALMISC2__CALSLOWCMPANA__SHIFT)
