#define DWC_DDRPHYA_MASTER0_P0__VREFINGLOBAL_P0__GLOBALVREFINTRIM__SHIFT 10
#define DWC_DDRPHYA_MASTER0_P0__VREFINGLOBAL_P0__GLOBALVREFINTRIM__FIELD (0xf << DWC_DDRPHYA_MASTER0_P0__VREFINGLOBAL_P0__GLOBALVREFINTRIM__SHIFT)
                
