#define DWC_DDRPHYA_MASTER0_P0__VREFINGLOBAL_P0__GLOBALVREFINMODE__SHIFT 14
#define DWC_DDRPHYA_MASTER0_P0__VREFINGLOBAL_P0__GLOBALVREFINMODE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P0__VREFINGLOBAL_P0__GLOBALVREFINMODE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P0__VREFINGLOBAL_P0__GLOBALVREFINMODE__M (0x1 << DWC_DDRPHYA_MASTER0_P0__VREFINGLOBAL_P0__GLOBALVREFINMODE__SHIFT)
                
