#define DWC_DDRPHYA_MASTER0_P0__DFIWRDATACSDESTMAP_P0__DFIWRDESTM0__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P0__DFIWRDATACSDESTMAP_P0__DFIWRDESTM0__SHIFT)
                
