#define DWC_DDRPHYA_MASTER0_P0__PHYINTERRUPTSTATUS__PHYINITCMPLT__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P0__PHYINTERRUPTSTATUS__PHYINITCMPLT__SHIFT)
#define DWC_DDRPHYA_MASTER0_P0__PHYINTERRUPTSTATUS__PHYINITCMPLT__M (0x1 << DWC_DDRPHYA_MASTER0_P0__PHYINTERRUPTSTATUS__PHYINITCMPLT__SHIFT)
                
