#define DWC_DDRPHYA_MASTER0_P0__PHYINTERRUPTSTATUS__PHYFWRESERVED__FIELD (0x1f << DWC_DDRPHYA_MASTER0_P0__PHYINTERRUPTSTATUS__PHYFWRESERVED__SHIFT)
                
