/* desc: Reserved for PHY training firmware use.*/
                
/* field: DWC_DDRPHYA_MASTER0_P1.DLLLOCKPARAM_P1.RFU_DLLLOCKPARAM_P1, pos: [12:0]*/
#define DWC_DDRPHYA_MASTER0_P1__DLLLOCKPARAM_P1__RFU_DLLLOCKPARAM_P1__SHIFT 0
