// register: DWC_DDRPHYA_MASTER0_P1.VREFINGLOBAL_P1
/* desc: This Register controls the PHY global VREF generator, and the PHY analog pad BP_VREF.
The mission mode function of the PHY VREF generator is to generate VrefDQ for the PHY RX function.
This register is written and configured by the PHY training firmware for mission mode function.*/
                
/* field: DWC_DDRPHYA_MASTER0_P1.VREFINGLOBAL_P1.GLOBALVREFINSEL, pos: [2:0] -- GlobalVrefInSel[1:0] controls the mode of the PHY VREF DAC and the BP_VREF pin
 - 2'b00 - PHY Vref DAC Range0 -- BP_VREF = Hi-Z
 - 2'b01 - Reserved Encoding
 - 2'b10 - PHY Vref DAC Range0 -- BP_VREF connected to PLL Analog Bus
 - 2'b11 - PHY Vref DAC Range0 -- BP_VREF connected to PHY Vref DAC
GlobalVrefInSel[2] controls the DAC range for internal Vref generation*/
#define DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINSEL__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINSEL__FIELD (0x7 << DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINSEL__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P1.VREFINGLOBAL_P1.GLOBALVREFINDAC, pos: [9:3] -- DAC code for internal Vref generation.
The DAC has two ranges; the range is set by GlobalVrefInSel[2]
 - RANGE0 : [GlobalVrefInSel[2] = 0]
 -- DAC Output Voltage = GlobalVrefInDAC == 6'h00 ? Hi-Z : 0.345*VDDQ + (0.005*GlobalVrefInDAC)*VDDQ
 - RANGE1 : [GlobalVrefInSel[2] = 1]
 -- DAC Output Voltage = GlobalVrefInDAC == 6'h00 ? Hi-Z : (0.005*(GlobalVrefInDAC-1))*VDDQ*/
#define DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINDAC__SHIFT 3
#define DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINDAC__FIELD (0x7f << DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINDAC__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P1.VREFINGLOBAL_P1.GLOBALVREFINTRIM, pos: [13:10] -- RSVD*/
#define DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINTRIM__SHIFT 10
#define DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINTRIM__FIELD (0xf << DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINTRIM__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P1.VREFINGLOBAL_P1.GLOBALVREFINMODE, pos: [14:14] -- RSVD*/
#define DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINMODE__SHIFT 14
#define DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINMODE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINMODE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINMODE__M (0x1 << DWC_DDRPHYA_MASTER0_P1__VREFINGLOBAL_P1__GLOBALVREFINMODE__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P1.DFIWRDATACSDESTMAP_P1
/* desc: This CSR must be default values in LPDDR3 and LPDDR4 modes
Maps dfi_wrdata_cs_n (write chip-select asserted low) to destination dimm timing group.
The full dfi interface has 72 values of dfi_wrdata_cs_n, with 8 per byte.
Byte db (0..8) uses values dfi_wrdata_cs_n[(db*8 + 7):(db*8 + 0)]
and this register, which is per byte, to determine the timing-control registers
to use for the asserted chip-select. For simplicity, the subfield description
does not include the byte offset for dfi_wrdata_cs_n.

Note: The example values below are the default/reset values.
If this register is written to all zeroes, then all writes will use Register Tx[Dq,Dqs]Dlyd0 timing.*/
                
/* field: DWC_DDRPHYA_MASTER0_P1.DFIWRDATACSDESTMAP_P1.DFIWRDESTM0, pos: [1:0] -- Maps dfi_wrdata_cs_n_p0[0] to dest DfiWrDestm0 timing

For example, if 0 dfi_wrdata_cs_n_p0[0] will use Register Tx[Dq,Dqs]DlyTg0 timing.*/
#define DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM0__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM0__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM0__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P1.DFIWRDATACSDESTMAP_P1.DFIWRDESTM1, pos: [3:2] -- Maps dfi_wrdata_cs_n_p0[1] to dest DfiWrDestm1 timing

For example, if 1 dfi_wrdata_cs_n_p0[0] will use Register Tx[Dq,Dqs]DlyTg1 timing.*/
#define DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM1__SHIFT 2
#define DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM1__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM1__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P1.DFIWRDATACSDESTMAP_P1.DFIWRDESTM2, pos: [5:4] -- Maps dfi_wrdata_cs_n_p0[2] to dest DfiWrDestm2 timing

For example, if 2 dfi_wrdata_cs_n_p0[0] will use Register Tx[Dq,Dqs]DlyTg2 timing.*/
#define DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM2__SHIFT 4
#define DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM2__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM2__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P1.DFIWRDATACSDESTMAP_P1.DFIWRDESTM3, pos: [7:6] -- Maps dfi_wrdata_cs_n_p0[3] to dest DfiWrDestm3 timing (use Register Tx[Dq,Dqs]DlyTg3)

For example, if 3 dfi_wrdata_cs_n_p0[0] will use Register Tx[Dq,Dqs]DlyTg3 timing.*/
#define DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM3__SHIFT 6
#define DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM3__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P1__DFIWRDATACSDESTMAP_P1__DFIWRDESTM3__SHIFT)
                
