// register: DWC_DDRPHYA_MASTER0_P2.TRISTATEMODECA_P2
/* desc: This register is used to control the PHY Dynamic Address/Command Tristate Feature, and the stopped MEMCLK state.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.TRISTATEMODECA_P2.DISDYNADRTRI, pos: [0:0] -- When DisDynAdrTri=1, Dynamic Tristating is disabled. Dynamic Tristating is on by default.
Dynamic Tristating should be disabled (DisDynAdrTri=1) for these modes:
 - DR3/2T if the controller cannot follow the 2T PHY tristate protocol.
 - DDR4/2T/2N if the controller cannot follow the 2T PHY tristate protocol.
 - LPDDR4
When DisDynAdrTri=0 (default),
 - In DDR4 mode, The following SDRAM pins can be dynamically tristated: A,BA,BG,ACT_n
 - In LPDDR3 mode, The following SDRAM pins can be dynamically tristated: CA[*]
 - In 1T mode, the PHY will tristate the relevant pins when all ranks are DESelected
 - In 2T mode (or geardown), the PHY will tristate the relevant pins when:
 -- DDR3 -- All ranks DESelected (all CS_L==1) AND [RAS_n,CAS_n,WE_n,BA0] = [1,1,1,0]
 -- DDR4 -- All ranks DESelected (all CS_L==1) AND [RAS_n,CAS_n,WE_n,BA0,ACT_n] = [1,1,1,0,1]
 - When in this mode, the controller should avoid sending the above patterns with any rank selected. [e.g. NOPs sent by the controller should have BA0 set to a non-zero value]*/
#define DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DISDYNADRTRI__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DISDYNADRTRI__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DISDYNADRTRI__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DISDYNADRTRI__M (0x1 << DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DISDYNADRTRI__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.TRISTATEMODECA_P2.DDR2TMODE, pos: [1:1] -- Must be set to 1 for Dynamic Tristate to work when CA bus is 2T or Geardown mode.
This CSR bit has no effect when DisDynAdrTri==1*/
#define DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DDR2TMODE__SHIFT 1
#define DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DDR2TMODE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DDR2TMODE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DDR2TMODE__M (0x1 << DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__DDR2TMODE__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.TRISTATEMODECA_P2.CKDISVAL, pos: [3:2] -- The PHY provides 4 memory clocks, n=0..3.
 - When the toggling of memory clock CK_t[n] is disabled with dfi_clk_disable[n]=1, the memory clock CK_t[n] is driven with Register CkDisVal[1].
 - When the toggling of memory clock CK_c[n] is disabled with dfi_clk_disable[n]=1, the memory clock CK_c[n] is driven with ~(Register CkDisVal[0]) (ie inverted).

Note that the non-toggling differential memory clock [CK_t[n],CK_c[n]] may be driven with any combination, LL,LH,HL,HH; the default [CK_t[n],CK_c[n]]=LH.*/
#define DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__CKDISVAL__SHIFT 2
#define DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__CKDISVAL__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P2__TRISTATEMODECA_P2__CKDISVAL__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.HWTMRL_P2
/* desc: HWT MaxReadLatency.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.HWTMRL_P2.HWTMRL_P2, pos: [4:0] -- This MASTER copy of MRL is used by the PHY training firmware only.*/
#define DWC_DDRPHYA_MASTER0_P2__HWTMRL_P2__HWTMRL_P2__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__HWTMRL_P2__HWTMRL_P2__FIELD (0x1f << DWC_DDRPHYA_MASTER0_P2__HWTMRL_P2__HWTMRL_P2__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.DQSPREAMBLECONTROL_P2
/* desc: For improved robustness in operating with DRAM timing drift, this register provides
controls for the width of the write DQS preamble and postamble, and controls for
the anticipated width of DQS preamble for reads.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.DQSPREAMBLECONTROL_P2.TWOTCKRXDQSPRE, pos: [0:0] -- Widens the RxDqsEn window to allow larger drift in the incoming read DQS
to take advantage of the larger/wider preamble generated by the DRAMSs
when the D4 DRAMS are configured with DDR4 MR4 A11 Read Preamble=1
for causing a 2nCK read preamble.
For LPDDR4, set to 1 for static read preamble,
set to 0 for toggling read preamble.

Note the nominal trained-to-center point will be earlier relative to
the first strobing edge of DQS than when not in this mode.*/
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKRXDQSPRE__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKRXDQSPRE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKRXDQSPRE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKRXDQSPRE__M (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKRXDQSPRE__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DQSPREAMBLECONTROL_P2.TWOTCKTXDQSPRE, pos: [1:1] -- For LPDDR4, all write operations are 2nCK such that this control must be set to 1.*/
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKTXDQSPRE__SHIFT 1
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKTXDQSPRE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKTXDQSPRE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKTXDQSPRE__M (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__TWOTCKTXDQSPRE__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DQSPREAMBLECONTROL_P2.POSITIONDFEINIT, pos: [4:2] -- For DDR4 phy only when receive DFE is enabled.
 - PositionDfeInit[2] is reserved
 - PositionDfeInit[1]=1 causes DfeInit to be asserted at the nominal time
 - PositionDfeInit[0] is reserved
PositionDfeInit=3'b010 is the nominal, recommended value for leading edge used by receiver, other values are reserved.*/
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__POSITIONDFEINIT__SHIFT 2
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__POSITIONDFEINIT__FIELD (0x7 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__POSITIONDFEINIT__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DQSPREAMBLECONTROL_P2.LP4TGLTWOTCKTXDQSPRE, pos: [5:5] -- Used in LPDDR4 mode to modify the early preamble when Register TwoTckTxDqsPre=1
- 0: level first-memclk preamble
- 1: toggling first-memclk preamble*/
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4TGLTWOTCKTXDQSPRE__SHIFT 5
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4TGLTWOTCKTXDQSPRE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4TGLTWOTCKTXDQSPRE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4TGLTWOTCKTXDQSPRE__M (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4TGLTWOTCKTXDQSPRE__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DQSPREAMBLECONTROL_P2.LP4POSTAMBLEEXT, pos: [6:6] -- In LPDDR4 mode must be set to extend the write postamble.
- 0: half-memclk postamble, as in D4
- 1: one-and-one-half-memclk postamble; see LPDDR4 Spec MR3, OP[1] WR PST, vendor-specific function.*/
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4POSTAMBLEEXT__SHIFT 6
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4POSTAMBLEEXT__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4POSTAMBLEEXT__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4POSTAMBLEEXT__M (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4POSTAMBLEEXT__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DQSPREAMBLECONTROL_P2.LP4STTCPREBRIDGERXEN, pos: [7:7] -- Used in LPDDR4 static-preamble mode to bridge the RxEn between two reads to the same timing group
when the bubble is 1 memclk.
LPDDR4 static-preamble mode is set in the DRAMs with MR1, OP[3]=0.*/
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4STTCPREBRIDGERXEN__SHIFT 7
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4STTCPREBRIDGERXEN__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4STTCPREBRIDGERXEN__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4STTCPREBRIDGERXEN__M (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__LP4STTCPREBRIDGERXEN__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DQSPREAMBLECONTROL_P2.WDQSEXTENSION, pos: [8:8] -- When set, DQS_T and DQS_C will be driven differentially to 0 and 1, respectively,
before and after a write burst, except during a memory read transaction.
See DesignWare Cores LPDDR4 MultiPHY: WDQS Extension Application Note.
Use of WDQSEXTENSION requires POdtTailWidth=3 and POdtStartDelay=00*/
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__WDQSEXTENSION__SHIFT 8
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__WDQSEXTENSION__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__WDQSEXTENSION__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__WDQSEXTENSION__M (0x1 << DWC_DDRPHYA_MASTER0_P2__DQSPREAMBLECONTROL_P2__WDQSEXTENSION__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.DMIPINPRESENT_P2
/* desc: This Register is used to instruct the PHY whether to enable the Read-DBI function on Lane8 of each DBYTE.
Only the LPDDR4 and DDR4 Protocols support the Read-DBI feature.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.DMIPINPRESENT_P2.RDDBIENABLED, pos: [0:0] -- This bit must be set to 1'b1 if Read-DBI is enabled in a connected DDR4 or LPDDR4 device.
If set, the following DRAM MR should also be set [DDR4.MR5.A12=1 or LPDDR4.MR3.OP[7]=1]*/
#define DWC_DDRPHYA_MASTER0_P2__DMIPINPRESENT_P2__RDDBIENABLED__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__DMIPINPRESENT_P2__RDDBIENABLED__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__DMIPINPRESENT_P2__RDDBIENABLED__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__DMIPINPRESENT_P2__RDDBIENABLED__M (0x1 << DWC_DDRPHYA_MASTER0_P2__DMIPINPRESENT_P2__RDDBIENABLED__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.ARDPTRINITVAL_P2
/* desc: Address/Command FIFO ReadPointer Initial Value*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.ARDPTRINITVAL_P2.ARDPTRINITVAL_P2, pos: [3:0] -- This is the initial Pointer Offset for the free-running FIFOs in the DBYTE and ACX4 hardips.
The units of this register are in UI. The pointer separation should be chosen to compensate for
all sources of skew and drift of the PHY DFICLK and PCLK networks. See "ARdPtrInitVal Impacts From Construction Skews" of the PUB databook.
This CSR must be programmed in Step C of the PHY Initialization sequence*/
#define DWC_DDRPHYA_MASTER0_P2__ARDPTRINITVAL_P2__ARDPTRINITVAL_P2__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__ARDPTRINITVAL_P2__ARDPTRINITVAL_P2__FIELD (0xf << DWC_DDRPHYA_MASTER0_P2__ARDPTRINITVAL_P2__ARDPTRINITVAL_P2__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.PROCODTTIMECTL_P2
/* desc: Controls timing of ProcOdt for DQ and DQS termination during reads.
The enabling and disabling of ProcOdt can be shifted with a granularity of 1UI.

If WDQSEXTENSION is enabled, this register should be set to 0x03.
Otherwise, use the recommended settings based on MEMCLK frequency and TwoTckRxDqsPre.
This will ensure that ProcOdt is enabled before the DQS preamble begins
and is not disabled until after the DQS postamble ends.

Recommended configuration if Register TwoTckRxDqsPre==1:
 - 0000MHz < memclk-freq <= 0933 ; Register POdtStartDelay= 2 ; Register POdtTailWidth=2
 - 0933MHz < memclk-freq <= 1200 ; Register POdtStartDelay= 0 ; Register POdtTailWidth=2
 - 1200MHz < memclk-freq <= NA ; Register POdtStartDelay= 0 ; Register POdtTailWidth=3

Recommended configuration if TwoTckRxDqsPre==0:
 - 0000MHz < memclk-freq <= 933 ; Register POdtStartDelay= 2 ; Register POdtTailWidth=2
 - 0933MHz < memclk-freq <= 1200 ; Register POdtStartDelay= 1 ; Register POdtTailWidth=2
 - 1200MHz < memclk-freq <= NA ; Register POdtStartDelay= 1 ; Register POdtTailWidth=3
See related CSR TxOdtDrvStren.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.PROCODTTIMECTL_P2.PODTTAILWIDTH, pos: [1:0] -- controls the length of the tail of ProcOdt, units of UI
- POdtTailWidth controls the time from closing the window to receive DQS to ProcODT deassertion, and can be set with values ranging from 0 to 3.
- The aforementioned timing is defined as (3 + POdtTailWidth + POdtTailWidthExt - csrTwiTckDqsPre) UIs.
- It is recommended to use this csr as the main timing configuration unit, with default value of 3. Note that this might not be the optimal value, since it is technology dependent. Refer to the PHY Databook for optimal settings.*/
#define DWC_DDRPHYA_MASTER0_P2__PROCODTTIMECTL_P2__PODTTAILWIDTH__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__PROCODTTIMECTL_P2__PODTTAILWIDTH__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P2__PROCODTTIMECTL_P2__PODTTAILWIDTH__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.PROCODTTIMECTL_P2.PODTSTARTDELAY, pos: [3:2] -- controls the start of ProcOdt, units of UI
 - 3 delay start 2 UI, maximum delay of start of ProcOdt
 - 2 delay start 1 UI,
 - 1 delay start 0 UI, default
 - 0 early by 1 UI,
The time from ProcODT assertion to opening the window to receive DQS is
than (10 - POdtStartDelay) UI. It may be up to 4 pclk smaller if small 	  coarse delays are used (used only at the lowest clock frequencies)*/
#define DWC_DDRPHYA_MASTER0_P2__PROCODTTIMECTL_P2__PODTSTARTDELAY__SHIFT 2
#define DWC_DDRPHYA_MASTER0_P2__PROCODTTIMECTL_P2__PODTSTARTDELAY__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P2__PROCODTTIMECTL_P2__PODTSTARTDELAY__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.PROCODTTIMECTL_P2.PODTTAILWIDTHEXT, pos: [5:4] -- controls the length of the tail of ProcOdt, units of UI
- POdtTailWidthExt controls the time from closing the window to receive DQS to ProcODT deassertion, and can be set with values ranging from 0 to 3.
- The aforementioned timing is defines as (3 + POdtTailWidth + POdtTailWidthExt - csrTwiTckDqsPre) UIs.
- It is recommended to use this csr as an extension to POdtTailWidth, and has a default value of 1. Note that this might not be the optimal value, since it is technology dependent. Refer to the PHY Databook for optimal settings.*/
#define DWC_DDRPHYA_MASTER0_P2__PROCODTTIMECTL_P2__PODTTAILWIDTHEXT__SHIFT 4
#define DWC_DDRPHYA_MASTER0_P2__PROCODTTIMECTL_P2__PODTTAILWIDTHEXT__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P2__PROCODTTIMECTL_P2__PODTTAILWIDTHEXT__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.DLLGAINCTL_P2
/* desc: Controls for the DllGain sequencing for locking and maintaining lock of the LCDL delay cells.
- The DllGain sequencer will start locking with the DllGainIV.
- As the end of locking approaches, the DllGain will be incremented in stages until, at the end of locking, the DllGain is the terminal values DllGainTV.
- 2^(5-DllGain) is fractional change in the DAC code MstPhase1UI[8:0] of Dll per pclk.
- Firmware uses values for DllGainIV, DllGainTV, and LcdlSeed0 that are optimized for minimum locking time. These controls are not to be configured by the user.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.DLLGAINCTL_P2.DLLGAINIV, pos: [3:0] -- Initial value of DllGain.*/
#define DWC_DDRPHYA_MASTER0_P2__DLLGAINCTL_P2__DLLGAINIV__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__DLLGAINCTL_P2__DLLGAINIV__FIELD (0xf << DWC_DDRPHYA_MASTER0_P2__DLLGAINCTL_P2__DLLGAINIV__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DLLGAINCTL_P2.DLLGAINTV, pos: [7:4] -- Terminal value of DllGain, ie the value in effect when locking is done
and the value used for maintaining lock, ie tracking pclk variation.
DllGainTV must be greater than or equal to DllGainIV.
The maximum value is 10.*/
#define DWC_DDRPHYA_MASTER0_P2__DLLGAINCTL_P2__DLLGAINTV__SHIFT 4
#define DWC_DDRPHYA_MASTER0_P2__DLLGAINCTL_P2__DLLGAINTV__FIELD (0xf << DWC_DDRPHYA_MASTER0_P2__DLLGAINCTL_P2__DLLGAINTV__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DLLGAINCTL_P2.DLLSEEDSEL, pos: [11:8] -- Reserved, must be configured to be 0.*/
#define DWC_DDRPHYA_MASTER0_P2__DLLGAINCTL_P2__DLLSEEDSEL__SHIFT 8
#define DWC_DDRPHYA_MASTER0_P2__DLLGAINCTL_P2__DLLSEEDSEL__FIELD (0xf << DWC_DDRPHYA_MASTER0_P2__DLLGAINCTL_P2__DLLSEEDSEL__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.DLLLOCKPARAM_P2
/* desc: Reserved for PHY training firmware use.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.DLLLOCKPARAM_P2.RFU_DLLLOCKPARAM_P2, pos: [12:0]*/
#define DWC_DDRPHYA_MASTER0_P2__DLLLOCKPARAM_P2__RFU_DLLLOCKPARAM_P2__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__DLLLOCKPARAM_P2__RFU_DLLLOCKPARAM_P2__FIELD (0x1fff << DWC_DDRPHYA_MASTER0_P2__DLLLOCKPARAM_P2__RFU_DLLLOCKPARAM_P2__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.DFIRDDATACSDESTMAP_P2
/* desc: This CSR must be default values in LPDDR3 and LPDDR4 modes.
Maps dfi_rddata_cs_n (read chip-select asserted low) to destination dimm timing group.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.DFIRDDATACSDESTMAP_P2.DFIRDDESTM0, pos: [1:0] -- Maps dfi_rddata_cs_n_p0[0] to dest DfiRdDestm0 timing.

For example, if 0 dfi_rddata_cs_n_p0[0] will use Register Rx[En,Clk]DlyTg0 timing.*/
#define DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM0__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM0__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM0__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DFIRDDATACSDESTMAP_P2.DFIRDDESTM1, pos: [3:2] -- Maps dfi_rddata_cs_n_p0[1] to dest DfiRdDestm1 timing.

For example, if 1 dfi_rddata_cs_n[_p01] will use Register Rx[En,Clk]DlyTg1 timing.*/
#define DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM1__SHIFT 2
#define DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM1__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM1__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DFIRDDATACSDESTMAP_P2.DFIRDDESTM2, pos: [5:4] -- Maps dfi_rddata_cs_n_p0[2] to dest DfiRdDestm2 timing.

For example, if 2 dfi_rddata_cs_n_p0[2] will use Register Rx[En,Clk]DlyTg2 timing.*/
#define DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM2__SHIFT 4
#define DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM2__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM2__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.DFIRDDATACSDESTMAP_P2.DFIRDDESTM3, pos: [7:6] -- Maps dfi_rddata_cs_n_p0[3] to dest DfiRdDestm3 timing.

For example, if 3 dfi_rddata_cs_n_p0[3] will use Register Rx[En,Clk]DlyTg3 timing.*/
#define DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM3__SHIFT 6
#define DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM3__FIELD (0x3 << DWC_DDRPHYA_MASTER0_P2__DFIRDDATACSDESTMAP_P2__DFIRDDESTM3__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.VREFINGLOBAL_P2
/* desc: This Register controls the PHY global VREF generator, and the PHY analog pad BP_VREF.
The mission mode function of the PHY VREF generator is to generate VrefDQ for the PHY RX function.
This register is written and configured by the PHY training firmware for mission mode function.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.VREFINGLOBAL_P2.GLOBALVREFINSEL, pos: [2:0] -- GlobalVrefInSel[1:0] controls the mode of the PHY VREF DAC and the BP_VREF pin
 - 2'b00 - PHY Vref DAC Range0 -- BP_VREF = Hi-Z
 - 2'b01 - Reserved Encoding
 - 2'b10 - PHY Vref DAC Range0 -- BP_VREF connected to PLL Analog Bus
 - 2'b11 - PHY Vref DAC Range0 -- BP_VREF connected to PHY Vref DAC
GlobalVrefInSel[2] controls the DAC range for internal Vref generation*/
#define DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINSEL__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINSEL__FIELD (0x7 << DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINSEL__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.VREFINGLOBAL_P2.GLOBALVREFINDAC, pos: [9:3] -- DAC code for internal Vref generation.
The DAC has two ranges; the range is set by GlobalVrefInSel[2]
 - RANGE0 : [GlobalVrefInSel[2] = 0]
 -- DAC Output Voltage = GlobalVrefInDAC == 6'h00 ? Hi-Z : 0.345*VDDQ + (0.005*GlobalVrefInDAC)*VDDQ
 - RANGE1 : [GlobalVrefInSel[2] = 1]
 -- DAC Output Voltage = GlobalVrefInDAC == 6'h00 ? Hi-Z : (0.005*(GlobalVrefInDAC-1))*VDDQ*/
#define DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINDAC__SHIFT 3
#define DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINDAC__FIELD (0x7f << DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINDAC__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.VREFINGLOBAL_P2.GLOBALVREFINTRIM, pos: [13:10] -- RSVD*/
#define DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINTRIM__SHIFT 10
#define DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINTRIM__FIELD (0xf << DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINTRIM__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P2.VREFINGLOBAL_P2.GLOBALVREFINMODE, pos: [14:14] -- RSVD*/
#define DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINMODE__SHIFT 14
#define DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINMODE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINMODE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINMODE__M (0x1 << DWC_DDRPHYA_MASTER0_P2__VREFINGLOBAL_P2__GLOBALVREFINMODE__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P2.DFIWRDATACSDESTMAP_P2
/* desc: This CSR must be default values in LPDDR3 and LPDDR4 modes
Maps dfi_wrdata_cs_n (write chip-select asserted low) to destination dimm timing group.
The full dfi interface has 72 values of dfi_wrdata_cs_n, with 8 per byte.
Byte db (0..8) uses values dfi_wrdata_cs_n[(db*8 + 7):(db*8 + 0)]
and this register, which is per byte, to determine the timing-control registers
to use for the asserted chip-select. For simplicity, the subfield description
does not include the byte offset for dfi_wrdata_cs_n.

Note: The example values below are the default/reset values.
If this register is written to all zeroes, then all writes will use Register Tx[Dq,Dqs]Dlyd0 timing.*/
                
/* field: DWC_DDRPHYA_MASTER0_P2.DFIWRDATACSDESTMAP_P2.DFIWRDESTM0, pos: [1:0] -- Maps dfi_wrdata_cs_n_p0[0] to dest DfiWrDestm0 timing

For example, if 0 dfi_wrdata_cs_n_p0[0] will use Register Tx[Dq,Dqs]DlyTg0 timing.*/
#define DWC_DDRPHYA_MASTER0_P2__DFIWRDATACSDESTMAP_P2__DFIWRDESTM0__SHIFT 0
