// register: DWC_DDRPHYA_DBYTE0_P3.TXODTDRVSTREN_B1_P3
/* desc: Selects desired impedance value for Host ODT.
Must be set by user before PHY initialization.
Setting for each protocol:
DDR3:
 - OdtStrenP - non-zero value
 - OdtStrenN - same as OdtStrenP
LPDDR3:
 - OdtStrenP - non-zero value
 - OdtStrenN - high-impedance
DDR4:
 - OdtStrenP - non-zero value
 - OdtStrenN - high-impedance
LPDDR4:
 - OdtStrenP - high-impedance
 - OdtStrenN - non-zero value
 - Register Block Offset Address 0x04d controls the lower DQ nibble
 - Register Block Offset Address 0x14d controls the upper DQ nibble*/
                
/* field: DWC_DDRPHYA_DBYTE0_P3.TXODTDRVSTREN_B1_P3.ODTSTRENP, pos: [5:0] -- Selects the ODT pull-up impedance.

Refer to Technology specific PHY DATABOOK for supported options
 - [ODTStren120P[2:0], ODTStren240P[1:0],ODTStren480P[0:0]]
 - 000_00_0 = High Impedance
 - 000_00_1 = 480 ohms
 - 000_01_0 = 240 ohms
 - 000_01_1 = 160 ohms
 - 001_00_0 = 120 ohms
 - 001_00_1 = 96.0 ohms
 - 001_01_0 = 80.0 ohms
 - 001_01_1 = 68.6 ohms
 - 011_00_0 = 60.0 ohms
 - 011_00_1 = 53.3 ohms
 - 011_01_0 = 48.0 ohms
 - 011_01_1 = 43.6 ohms
 - 111_00_0 = 40.0 ohms
 - 111_00_1 = 36.9 ohms
 - 111_01_0 = 34.3 ohms
 - 111_01_1 = 32.0 ohms
 - 111_11_0 = 30.0 ohms
 - 111_11_1 = 28.2 ohms*/
#define DWC_DDRPHYA_DBYTE0_P3__TXODTDRVSTREN_B1_P3__ODTSTRENP__SHIFT 0
#define DWC_DDRPHYA_DBYTE0_P3__TXODTDRVSTREN_B1_P3__ODTSTRENP__FIELD (0x3f << DWC_DDRPHYA_DBYTE0_P3__TXODTDRVSTREN_B1_P3__ODTSTRENP__SHIFT)
                
