/* desc: HWT MaxReadLatency.*/
                
/* field: DWC_DDRPHYA_MASTER0_P3.HWTMRL_P3.HWTMRL_P3, pos: [4:0] -- This MASTER copy of MRL is used by the PHY training firmware only.*/
#define DWC_DDRPHYA_MASTER0_P3__HWTMRL_P3__HWTMRL_P3__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P3__HWTMRL_P3__HWTMRL_P3__FIELD (0x1f << DWC_DDRPHYA_MASTER0_P3__HWTMRL_P3__HWTMRL_P3__SHIFT)
                
//----------------------------------------------------------------------------
// register: DWC_DDRPHYA_MASTER0_P3.DQSPREAMBLECONTROL_P3
/* desc: For improved robustness in operating with DRAM timing drift, this register provides
controls for the width of the write DQS preamble and postamble, and controls for
the anticipated width of DQS preamble for reads.*/
                
/* field: DWC_DDRPHYA_MASTER0_P3.DQSPREAMBLECONTROL_P3.TWOTCKRXDQSPRE, pos: [0:0] -- Widens the RxDqsEn window to allow larger drift in the incoming read DQS
to take advantage of the larger/wider preamble generated by the DRAMSs
when the D4 DRAMS are configured with DDR4 MR4 A11 Read Preamble=1
for causing a 2nCK read preamble.
For LPDDR4, set to 1 for static read preamble,
set to 0 for toggling read preamble.

Note the nominal trained-to-center point will be earlier relative to
the first strobing edge of DQS than when not in this mode.*/
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKRXDQSPRE__SHIFT 0
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKRXDQSPRE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKRXDQSPRE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKRXDQSPRE__M (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKRXDQSPRE__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P3.DQSPREAMBLECONTROL_P3.TWOTCKTXDQSPRE, pos: [1:1] -- For LPDDR4, all write operations are 2nCK such that this control must be set to 1.*/
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKTXDQSPRE__SHIFT 1
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKTXDQSPRE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKTXDQSPRE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKTXDQSPRE__M (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__TWOTCKTXDQSPRE__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P3.DQSPREAMBLECONTROL_P3.POSITIONDFEINIT, pos: [4:2] -- For DDR4 phy only when receive DFE is enabled.
 - PositionDfeInit[2] is reserved
 - PositionDfeInit[1]=1 causes DfeInit to be asserted at the nominal time
 - PositionDfeInit[0] is reserved
PositionDfeInit=3'b010 is the nominal, recommended value for leading edge used by receiver, other values are reserved.*/
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__POSITIONDFEINIT__SHIFT 2
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__POSITIONDFEINIT__FIELD (0x7 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__POSITIONDFEINIT__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P3.DQSPREAMBLECONTROL_P3.LP4TGLTWOTCKTXDQSPRE, pos: [5:5] -- Used in LPDDR4 mode to modify the early preamble when Register TwoTckTxDqsPre=1
- 0: level first-memclk preamble
- 1: toggling first-memclk preamble*/
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4TGLTWOTCKTXDQSPRE__SHIFT 5
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4TGLTWOTCKTXDQSPRE__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4TGLTWOTCKTXDQSPRE__SHIFT)
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4TGLTWOTCKTXDQSPRE__M (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4TGLTWOTCKTXDQSPRE__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P3.DQSPREAMBLECONTROL_P3.LP4POSTAMBLEEXT, pos: [6:6] -- In LPDDR4 mode must be set to extend the write postamble.
- 0: half-memclk postamble, as in D4
- 1: one-and-one-half-memclk postamble; see LPDDR4 Spec MR3, OP[1] WR PST, vendor-specific function.*/
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4POSTAMBLEEXT__SHIFT 6
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4POSTAMBLEEXT__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4POSTAMBLEEXT__SHIFT)
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4POSTAMBLEEXT__M (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4POSTAMBLEEXT__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P3.DQSPREAMBLECONTROL_P3.LP4STTCPREBRIDGERXEN, pos: [7:7] -- Used in LPDDR4 static-preamble mode to bridge the RxEn between two reads to the same timing group
when the bubble is 1 memclk.
LPDDR4 static-preamble mode is set in the DRAMs with MR1, OP[3]=0.*/
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4STTCPREBRIDGERXEN__SHIFT 7
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4STTCPREBRIDGERXEN__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4STTCPREBRIDGERXEN__SHIFT)
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4STTCPREBRIDGERXEN__M (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__LP4STTCPREBRIDGERXEN__SHIFT)
                
/* field: DWC_DDRPHYA_MASTER0_P3.DQSPREAMBLECONTROL_P3.WDQSEXTENSION, pos: [8:8] -- When set, DQS_T and DQS_C will be driven differentially to 0 and 1, respectively,
before and after a write burst, except during a memory read transaction.
See DesignWare Cores LPDDR4 MultiPHY: WDQS Extension Application Note.
Use of WDQSEXTENSION requires POdtTailWidth=3 and POdtStartDelay=00*/
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__WDQSEXTENSION__SHIFT 8
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__WDQSEXTENSION__FIELD (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__WDQSEXTENSION__SHIFT)
#define DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__WDQSEXTENSION__M (0x1 << DWC_DDRPHYA_MASTER0_P3__DQSPREAMBLECONTROL_P3__WDQSEXTENSION__SHIFT)
                
