#define DWC_DDRPHYA_MASTER0_P3__DMIPINPRESENT_P3__RDDBIENABLED__M (0x1 << DWC_DDRPHYA_MASTER0_P3__DMIPINPRESENT_P3__RDDBIENABLED__SHIFT)
                
