#define DWC_DDRPHYA_MASTER0_P3__VREFINGLOBAL_P3__GLOBALVREFINDAC__FIELD (0x7f << DWC_DDRPHYA_MASTER0_P3__VREFINGLOBAL_P3__GLOBALVREFINDAC__SHIFT)
                
