#define DWC_DDRPHYA_MASTER0_P3__VREFINGLOBAL_P3__GLOBALVREFINTRIM__FIELD (0xf << DWC_DDRPHYA_MASTER0_P3__VREFINGLOBAL_P3__GLOBALVREFINTRIM__SHIFT)
                
